package local.tv.launcher;
import android.content.Context;
import android.content.SharedPreferences;
import org.json.*;
import java.io.*;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
/** Blocking provider client: call from a background executor only. */
public final class CatalogClient {
 private final SharedPreferences credentials; private final Cache cache; private volatile long generation;
 public CatalogClient(Context context){credentials=context.getSharedPreferences("catalog_private",Context.MODE_PRIVATE);credentials.edit().remove("credential").apply();cache=new Cache(context,"catalog_metadata",8*1024*1024);}
 public boolean hasCredential(){return !BuildConfig.TMDB_CREDENTIAL.isEmpty();}
 /** Retained source compatibility only; bundled configuration is authoritative. */
 public synchronized void setCredential(String ignored){credentials.edit().remove("credential").commit();generation++;cache.clear();}

 public String region(){return credentials.getString("region","IN");}
 public synchronized void setRegion(String value){String next=NetworkPolicy.region(value);credentials.edit().putString("region",next).commit();generation++;cache.clear();}
 private JSONObject request(String path)throws Exception{String token=BuildConfig.TMDB_CREDENTIAL;if(token.isEmpty())throw new IOException("Credential required");Map<String,String> headers=new HashMap<>();headers.put("Accept","application/json");String url="https://api.themoviedb.org/3"+path+(path.contains("?")?"&":"?")+"language=en-US";if(NetworkPolicy.apiKey(token))url+="&api_key="+token;else headers.put("Authorization","Bearer "+token);return new JSONObject(new String(SecureHttp.get(url,headers,1024*1024),StandardCharsets.UTF_8));}
 public JSONObject home(){return load("home",()->{JSONArray featured=new JSONArray();String[] types={"movie","tv","movie","movie"};int[] ids={693134,95396,157336,414906};for(int i=0;i<ids.length;i++){try{JSONObject item=normalize(request("/"+types[i]+"/"+ids[i]+"?append_to_response=credits"),types[i]);if(item!=null)featured.put(item);}catch(Exception ignored){}}JSONArray items=normalizeList(request("/trending/all/week").optJSONArray("results"));if(items.length()==0)throw new IOException();return envelope(items,featured,"live","");});}
 public JSONObject search(String query){String q=NetworkPolicy.query(query);if(q.isEmpty())return envelope(new JSONArray(),new JSONArray(),hasCredential()?"live":"error",hasCredential()?"Enter a title":"Catalog configuration unavailable");return load("search:v2:"+q,()->{
  JSONArray multi=normalizeList(request("/search/multi?include_adult=false&query="+URLEncoder.encode(q,"UTF-8")).optJSONArray("results"));JSONArray items=new JSONArray();
  for(String type:new String[]{"movie","tv"}){try{JSONArray genres=genreList(type);for(int i=0;i<genres.length();i++){JSONObject genre=genres.optJSONObject(i);if(genre==null||!NetworkPolicy.genreMatches(q,genre.optString("name")))continue;JSONObject found=request("/discover/"+type+"?include_adult=false&sort_by=popularity.desc&with_genres="+genre.getInt("id"));JSONArray rows=found.optJSONArray("results");if(rows!=null)for(int j=0;j<rows.length();j++){JSONObject row=rows.optJSONObject(j);if(row!=null)row.put("media_type",type);}items=merge(items,normalizeList(rows));}}catch(Exception ignored){}}
  return envelope(merge(items,multi),new JSONArray(),"live","");});}
 private JSONArray genreList(String type)throws Exception{String key="genres:"+type;JSONObject saved=cache.read(key);if(saved!=null&&cache.fresh(key,3600000))return saved.optJSONArray("genres");try{JSONObject value=request("/genre/"+type+"/list");cache.write(key,value);return value.getJSONArray("genres");}catch(Exception e){if(saved!=null&&saved.optJSONArray("genres")!=null)return saved.optJSONArray("genres");throw e;}}
 public JSONObject details(String type,int id){if(!NetworkPolicy.validType(type)||!NetworkPolicy.validId(id))return envelope(new JSONArray(),new JSONArray(),"error","Invalid title");final String selectedRegion=region();return load("details:v2:"+selectedRegion+":"+type+":"+id,()->{JSONObject raw=request("/"+type+"/"+id+"?append_to_response=credits,watch/providers");JSONObject item=normalize(raw,type);if(item==null)throw new IOException();JSONObject providers=providers(raw,selectedRegion);item.put("providers",providers);JSONObject result=envelope(new JSONArray().put(item),new JSONArray(),"live","");result.put("item",item).put("providers",providers);return result;});}
 private JSONObject providers(JSONObject raw,String region)throws JSONException{JSONArray offers=new JSONArray();JSONObject watch=raw.optJSONObject("watch/providers"),results=watch==null?null:watch.optJSONObject("results"),local=results==null?null:results.optJSONObject(region);String link="";if(local!=null){String candidate=local.optString("link","");if(NetworkPolicy.providerLink(candidate))link=candidate;for(String type:new String[]{"flatrate","rent","buy"}){JSONArray rows=local.optJSONArray(type);if(rows!=null)for(int i=0;i<rows.length()&&offers.length()<40;i++){JSONObject row=rows.optJSONObject(i);if(row!=null&&row.optInt("provider_id")>0&&!row.optString("provider_name").isEmpty())offers.put(new JSONObject().put("id",row.optInt("provider_id")).put("name",row.optString("provider_name")).put("type",type));}}}return new JSONObject().put("region",region).put("source","JustWatch via TMDB").put("offers",offers).put("link",link);}
 private interface Fetch{JSONObject get()throws Exception;}
 private JSONObject load(String key,Fetch fetch){if(!hasCredential())return envelope(new JSONArray(),new JSONArray(),"error","Catalog configuration unavailable");long version=generation;JSONObject saved=cache.read(key);if(saved!=null&&cache.fresh(key,3600000))return status(saved,"cached","Cached within the last hour",false);try{JSONObject result=fetch.get();if(version==generation)cache.write(key,result);return result;}catch(Exception ignored){return saved==null?envelope(new JSONArray(),new JSONArray(),"error","Catalog unavailable; check connection"):status(saved,"cached","Offline: showing previously fetched catalog",true);}}
 private static JSONObject status(JSONObject o,String s,String message,boolean stale){try{o.put("status",s).put("message",message).put("stale",stale);}catch(JSONException ignored){}return o;}
 private static JSONObject envelope(JSONArray items,JSONArray featured,String status,String message){JSONObject o=new JSONObject();try{o.put("items",items).put("featured",featured).put("status",status).put("message",message).put("stale",false);}catch(JSONException ignored){}return o;}
 private JSONArray normalizeList(JSONArray rows)throws JSONException{JSONArray out=new JSONArray();if(rows!=null)for(int i=0;i<rows.length()&&out.length()<24;i++){JSONObject raw=rows.optJSONObject(i);if(raw==null||raw.optBoolean("adult",false))continue;if("person".equals(raw.optString("media_type"))){JSONArray known=raw.optJSONArray("known_for");if(known!=null)for(int j=0;j<known.length()&&out.length()<24;j++){JSONObject row=known.optJSONObject(j);if(row!=null)add(out,normalize(row,row.optString("media_type")));}}else add(out,normalize(raw,raw.optString("media_type")));}return out;}
 private static void add(JSONArray out,JSONObject item)throws JSONException{if(item==null||out.length()>=24)return;for(int i=0;i<out.length();i++)if(out.getJSONObject(i).optString("key").equals(item.optString("key")))return;out.put(item);}
 private static JSONArray merge(JSONArray first,JSONArray second)throws JSONException{for(int i=0;i<second.length();i++)add(first,second.getJSONObject(i));return first;}
 private JSONObject normalize(JSONObject r,String type)throws JSONException{int id=r.optInt("id");if(!NetworkPolicy.validType(type)||!NetworkPolicy.validId(id)||r.optBoolean("adult",false))return null;String title=r.optString("title",r.optString("name",""));if(title.isEmpty())return null;JSONObject out=new JSONObject();String date=r.optString("release_date",r.optString("first_air_date",""));out.put("key",type+":"+id).put("id",id).put("mediaType",type).put("title",title).put("year",date.matches("[0-9]{4}-.*")?date.substring(0,4):"").put("overview",r.optString("overview","")).put("art",image(r.optString("backdrop_path"),"w1280")).put("poster",image(r.optString("poster_path"),"w500")).put("tagline",r.optString("tagline",""));JSONArray genres=new JSONArray();JSONArray gs=r.optJSONArray("genres");if(gs!=null)for(int i=0;i<gs.length()&&i<12;i++){JSONObject g=gs.optJSONObject(i);if(g!=null&&!g.optString("name").isEmpty())genres.put(g.optString("name"));}out.put("genres",genres);int runtime=r.optInt("runtime",0);if(runtime>0)out.put("runtime",runtime);JSONArray cast=new JSONArray();JSONObject credits=r.optJSONObject("credits");JSONArray people=credits==null?null:credits.optJSONArray("cast");if(people!=null)for(int i=0;i<people.length()&&i<12;i++){JSONObject p=people.optJSONObject(i);if(p!=null)cast.put(new JSONObject().put("name",p.optString("name")).put("character",p.optString("character")).put("photo",image(p.optString("profile_path"),"w500")));}out.put("cast",cast);return out;}
 private static String image(String path,String size){String url="https://image.tmdb.org/t/p/"+size+path;return NetworkPolicy.imageUrl(url)?url:"";}
 /** Native private cache keys are digests of metadata identifiers, never credentials. */
 static final class Cache {
  final File dir;final long cap;Cache(Context c,String name,long cap){dir=new File(c.getCacheDir(),name);dir.mkdirs();this.cap=cap;}
  private File file(String key){try{byte[] bytes=MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));StringBuilder hex=new StringBuilder();for(byte b:bytes)hex.append(String.format(Locale.ROOT,"%02x",b&255));return new File(dir,hex+".json");}catch(Exception e){throw new IllegalStateException("Cache unavailable");}}
  synchronized boolean fresh(String key,long ttl){File f=file(key);long age=System.currentTimeMillis()-f.lastModified();return f.exists()&&age>=0&&age<ttl;}
  synchronized JSONObject read(String key){File f=file(key);if(!f.isFile()||f.length()>1024*1024)return null;try(FileInputStream in=new FileInputStream(f);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>1024*1024)return null;out.write(b,0,n);}return new JSONObject(new String(out.toByteArray(),StandardCharsets.UTF_8));}catch(Exception e){return null;}}
  synchronized void write(String key,JSONObject value){byte[] data=value.toString().getBytes(StandardCharsets.UTF_8);if(data.length>1024*1024)return;File target=file(key),temp=new File(dir,"pending.tmp");try{try(FileOutputStream out=new FileOutputStream(temp)){out.write(data);}if(!temp.renameTo(target))temp.delete();File[] files=dir.listFiles();if(files==null)return;Arrays.sort(files,Comparator.comparingLong(File::lastModified));long total=0;for(File f:files)total+=f.length();for(File f:files){if(total<=cap)break;long size=f.length();if(f.delete())total-=size;}}catch(Exception ignored){temp.delete();}}
  synchronized void clear(){File[] files=dir.listFiles();if(files!=null)for(File f:files)f.delete();}
 }
}
